import {eq} from 'drizzle-orm';
import {getDatabase} from '../db/client.js';
import {xiangqiRooms} from '../db/xiangqi-schema.js';
import domain from '../games/xiangqi/domain.cjs';

/** Anonymous identities are generated by the server; clients never submit seats or boards. */
export async function playXiangqi(who:string,event:domain.Event,now=Date.now()) {
  const db=getDatabase();
  if(event.action==='create') {
    const room=domain.create(who,event.requestId ?? '',now);
    await db.insert(xiangqiRooms).values({code:room._id,state:room,version:0,expiresAt:new Date(room.expiresAt)}).onConflictDoNothing();
    const [saved]=await db.select().from(xiangqiRooms).where(eq(xiangqiRooms.code,room._id));
    if(!saved || saved.state.red!==who) throw new domain.Fault('CONFLICT','请重新创建棋房。');
    return domain.view(saved.state,who,now);
  }
  const code=domain.code(event.code);
  if(event.action==='get') {
    const [row]=await db.select().from(xiangqiRooms).where(eq(xiangqiRooms.code,code));
    if(!row) throw new domain.Fault('NOT_FOUND','棋房不存在，请检查邀请链接。');
    return domain.view(row.state,who,now);
  }
  return db.transaction(async tx=>{
    const [row]=await tx.select().from(xiangqiRooms).where(eq(xiangqiRooms.code,code)).for('update');
    if(!row) throw new domain.Fault('NOT_FOUND','棋房不存在，请检查邀请链接。');
    const next=domain.reduce(row.state,who,event,now);
    if(next.version!==row.version) await tx.update(xiangqiRooms).set({state:next,version:next.version}).where(eq(xiangqiRooms.code,code));
    return domain.view(next,who,now);
  });
}
